new='''    /// Append a message a send accepted, together with what accepting it owes the queue:
    /// the deduplication token that admitted it, remembered only when the message was
    /// sequenced (a FIFO queue), and the `AWS/SQS` sent counters for `size` bytes.
    pub fn enqueue_sent(
        &mut self,
        message: StoredMessage,
        deduplication_key: Option<(String, String)>,
        size: usize,
        now: SystemTime,
    ) {
        let admitted = deduplication_key.zip(message.sequence_number.clone()).map(
            |(key, sequence_number)| {
                let record = Deduplication {
                    message_id: message.message_id.clone(),
                    sequence_number,
                    accepted_at: now,
                };
                (key, record)
            },
        );
        self.messages.push_back(message);
        if let Some((key, record)) = admitted {
            self.record_deduplication(key, record);
        }
        self.count_sent(size, now);
    }

